import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.autotune(
    configs=[
        triton.Config({"BLOCK_OW": 16}, num_warps=4, num_stages=2),
    ],
    key=["OW"],
)
@triton.jit
def avg_pool2d_kernel(
    input_ptr,
    output_ptr,
    W,
    OW,
    in_stride_nc,
    out_stride_nc,
    KERNEL_SIZE: tl.constexpr,
    POOL_STRIDE: tl.constexpr,
    BLOCK_OW: tl.constexpr,
    OUTPUT_BF16: tl.constexpr,
):
    pid_nc = tl.program_id(0)
    pid_oh = tl.program_id(1)
    pid_ow_tile = tl.program_id(2)

    ow_offsets = pid_ow_tile * BLOCK_OW + tl.arange(0, BLOCK_OW)
    ow_mask = ow_offsets < OW

    in_base = input_ptr + pid_nc.to(tl.int64) * in_stride_nc
    out_base = output_ptr + pid_nc.to(tl.int64) * out_stride_nc

    acc = tl.zeros((BLOCK_OW,), dtype=tl.float32)

    h_start = pid_oh * POOL_STRIDE

    for kh in range(KERNEL_SIZE):
        h_in = h_start + kh
        row_offset = h_in * W
        for kw in range(KERNEL_SIZE):
            w_in = ow_offsets * POOL_STRIDE + kw
            vals = tl.load(in_base + row_offset + w_in, mask=ow_mask, other=0.0)
            acc += vals.to(tl.float32)

    inv_area = 1.0 / (KERNEL_SIZE * KERNEL_SIZE)
    result = acc * inv_area

    out_offset = pid_oh * OW + ow_offsets
    if OUTPUT_BF16:
        tl.store(out_base + out_offset, result.to(tl.bfloat16), mask=ow_mask)
    else:
        tl.store(out_base + out_offset, result, mask=ow_mask)


class Model(nn.Module):
    def __init__(self, kernel_size: int, stride: int = None, padding: int = 0):
        super(Model, self).__init__()
        self.kernel_size = kernel_size
        self.stride = stride if stride is not None else kernel_size
        self.padding = padding

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        N, C, H, W = x.shape
        x = x.contiguous()

        OH = (H + 2 * self.padding - self.kernel_size) // self.stride + 1
        OW = (W + 2 * self.padding - self.kernel_size) // self.stride + 1

        output = torch.empty(N, C, OH, OW, device=x.device, dtype=x.dtype)

        NC = N * C
        in_stride_nc = H * W
        out_stride_nc = OH * OW
        is_bf16 = x.dtype == torch.bfloat16

        grid = lambda META: (NC, OH, triton.cdiv(OW, META["BLOCK_OW"]))

        avg_pool2d_kernel[grid](
            x,
            output,
            W,
            OW,
            in_stride_nc,
            out_stride_nc,
            KERNEL_SIZE=self.kernel_size,
            POOL_STRIDE=self.stride,
            OUTPUT_BF16=is_bf16,
        )

        return output


batch_size = 16
channels = 64
height = 2048
